#!/usr/bin/env node

/**
 * Script to create and confirm test user for E2E tests
 * Run this script to set up your test user account
 */

import { createClient } from '@supabase/supabase-js'
import { readFileSync } from 'fs'
import { resolve } from 'path'

// Load environment variables from .env.local
try {
  const envPath = resolve(process.cwd(), '.env.local')
  const envContent = readFileSync(envPath, 'utf-8')
  envContent.split('\n').forEach(line => {
    const trimmed = line.trim()
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=')
      if (key && valueParts.length > 0) {
        process.env[key] = valueParts.join('=')
      }
    }
  })
} catch (error) {
  console.error('❌ Could not load .env.local file:', error.message)
  process.exit(1)
}

const supabaseUrl = process.env.VITE_SUPABASE_URL
const supabaseKey = process.env.VITE_SUPABASE_ANON_KEY
const testEmail = process.env.TEST_USER_EMAIL || 'test.e2e@example.com'
const testPassword = process.env.TEST_USER_PASSWORD || 'TestPassword123!'

if (!supabaseUrl || !supabaseKey) {
  console.error('❌ Missing Supabase credentials in .env.local')
  console.error('   Required: VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY')
  process.exit(1)
}

const supabase = createClient(supabaseUrl, supabaseKey)

async function setupTestUser() {
  console.log('🚀 Setting up test user for E2E tests...')
  console.log('📧 Email:', testEmail)

  try {
    // Try to sign up the user
    const { data, error } = await supabase.auth.signUp({
      email: testEmail,
      password: testPassword,
      options: {
        emailRedirectTo: undefined // Skip email confirmation for test users
      }
    })

    if (error) {
      if (error.message.includes('already registered')) {
        console.log('✅ Test user already exists')
      } else {
        console.error('❌ Error creating test user:', error.message)

        // Try to sign in to check if user exists
        console.log('🔄 Attempting to sign in with existing credentials...')
        const { error: signInError } = await supabase.auth.signInWithPassword({
          email: testEmail,
          password: testPassword
        })

        if (signInError) {
          console.error('❌ Sign in failed:', signInError.message)
          console.log('💡 You may need to:')
          console.log('   1. Create this user manually in Supabase dashboard')
          console.log('   2. Or disable email confirmation in Auth settings')
          console.log('   3. Or use a different email address')
        } else {
          console.log('✅ Test user exists and credentials work!')
        }
      }
    } else {
      console.log('✅ Test user created successfully!')
      if (data?.user?.email_confirmed_at) {
        console.log('✅ Email confirmed automatically')
      } else {
        console.log('⚠️  Email confirmation may be required')
        console.log('💡 Check Supabase Auth settings to disable email confirmation for easier testing')
      }
    }

    // Test the connection
    console.log('🧪 Testing authentication...')
    const { error: testError } = await supabase.auth.signInWithPassword({
      email: testEmail,
      password: testPassword
    })

    if (testError) {
      console.error('❌ Authentication test failed:', testError.message)
      console.log('💡 This may indicate email confirmation is required')
    } else {
      console.log('✅ Authentication test passed!')
      console.log('🎉 Test user is ready for E2E tests')
    }

  } catch (error) {
    console.error('❌ Unexpected error:', error)
  }
}

setupTestUser()

