test.describe('Authenticated Application Tests', () => {
  test.beforeEach(async ({ page }) => {
    // These tests require authentication - skip if not available
    if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
      test.skip('Skipping authenticated tests - no Supabase credentials available')
    }

    // Navigate to gear page (should be authenticated via storage state)
    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')
  })

  test('should access gear page when authenticated', async ({ page }) => {
    // Should be on gear page, not redirected to login
    expect(page.url()).toContain('/gear')

    // Should have gear-related content
    const title = await page.title()
    expect(title).toBeTruthy()

    // Should have main navigation or content indicators
    const mainContent = page.locator('main, [role="main"], .max-w-7xl')
    await expect(mainContent).toBeVisible({ timeout: 5000 })
  })

  test('should show gear management interface', async ({ page }) => {
    // Look for key gear management elements
    const searchBox = page.locator('input[placeholder*="search"], input[type="search"]')
    const addButton = page.locator('button', { hasText: /add/i }).or(page.locator('button:has(svg)'))

    // At least one of these should be present for gear management
    const hasSearchOrAdd = (await searchBox.count()) > 0 || (await addButton.count()) > 0
    expect(hasSearchOrAdd).toBe(true)
  })
})

