import { test, expect } from '@playwright/test'

test.describe('Debug Tests', () => {
  test('debug login page (no auth required)', async ({ page }) => {
    await page.goto('/login')
    await page.waitForLoadState('domcontentloaded')

    const title = await page.title()
    console.log('📄 Page title:', title)

    const forms = await page.locator('form').count()
    console.log('📋 Forms found:', forms)

    const inputs = await page.locator('input').count()
    console.log('📝 Total inputs found:', inputs)

    for (let i = 0; i < inputs; i++) {
      const input = page.locator('input').nth(i)
      const id = await input.getAttribute('id')
      const type = await input.getAttribute('type')
      const name = await input.getAttribute('name')
      const placeholder = await input.getAttribute('placeholder')

      console.log(`📝 Input ${i}: id=${id}, type=${type}, name=${name}, placeholder=${placeholder}`)
    }

    const signInText = await page.locator('text="Sign In"').isVisible()
    console.log('🔐 Sign in text found:', signInText)

    const currentUrl = page.url()
    console.log('🌐 Current URL:', currentUrl)

    const errorElements = await page.locator('.error, [role="alert"], .text-red-500').count()
    console.log('❌ Error elements found:', errorElements)

    // This is just a debug test, no assertions needed
  })

  test('debug authenticated gear page', async ({ page }) => {
    // Skip if no Supabase credentials
    if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
      test.skip('Skipping authenticated debug test - no Supabase credentials available')
    }

    await page.goto('/gear')
    await page.waitForTimeout(2000)

    const currentUrl = page.url()
    console.log('🎯 Gear page URL:', currentUrl)

    const title = await page.title()
    console.log('📄 Page title:', title)

    const mainElements = await page.locator('main, [role="main"]').count()
    console.log('🏠 Main elements:', mainElements)

    const buttons = await page.locator('button').count()
    console.log('🔘 Buttons found:', buttons)

    const inputs = await page.locator('input').count()
    console.log('📝 Inputs found:', inputs)

    const headings = await page.locator('h1, h2, h3').count()
    console.log('📋 Headings found:', headings)

    // List first few button texts
    for (let i = 0; i < Math.min(buttons, 3); i++) {
      const buttonText = await page.locator('button').nth(i).textContent()
      console.log(`🔘 Button ${i}: "${buttonText?.trim()}"`)
    }

    // Check for gear form data attribute
    const gearForms = await page.locator('[data-gear-form]').count()
    console.log('📋 Gear forms found:', gearForms)

    // Check for add buttons (using more specific selectors to avoid strict mode violations)
    const addButtons = await page.locator('button:has-text("Add")').count()
    console.log('➕ Add buttons found:', addButtons)
  })
})

