import { test, expect } from '@playwright/test'

// Gear page functionality tests - requires authentication
test.describe('Gear Page', () => {
  test.beforeEach(async ({ page }) => {
    // Skip if no Supabase credentials
    if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
      test.skip('Skipping authenticated tests - no Supabase credentials available')
    }

    // Navigate to gear page (authentication handled by storage state)
    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')

    // Wait for main content to load
    await page.waitForSelector('main, [role="main"], .max-w-7xl, h1', { timeout: 10000 })
  })

  test('loads successfully when authenticated', async ({ page }) => {
    // Should be on gear page, not redirected to login
    expect(page.url()).toContain('/gear')
    expect(page.url()).not.toContain('/login')

    // Should have proper page title
    const title = await page.title()
    expect(title).toBeTruthy()
    expect(title).toContain('BetterPack')
  })

  test('displays main content areas', async ({ page }) => {
    // Should have main content container
    const mainContent = page.locator('main, [role="main"], .max-w-7xl')
    await expect(mainContent).toBeVisible()

    // Should have page headings
    const headings = page.locator('h1, h2, h3')
    expect(await headings.count()).toBeGreaterThan(0)
  })

  test('shows gear management interface', async ({ page }) => {
    // Look for gear management elements
    const searchBox = page.locator('input[placeholder*="search" i], input[type="search"]')
    const addButton = page.getByRole('button', { name: /add/i })
    const filterElements = page.locator('button').filter({ hasText: /categor/i })

    // Should have at least one management interface element
    const interfaceElements = [
      await searchBox.count(),
      await addButton.count(), 
      await filterElements.count()
    ]

    const hasInterface = interfaceElements.some(count => count > 0)
    expect(hasInterface).toBe(true)
  })

  test('is responsive on mobile', async ({ page }) => {
    // Test mobile viewport
    await page.setViewportSize({ width: 375, height: 667 })
    await page.reload()
    await page.waitForLoadState('domcontentloaded')

    // Should still be on gear page
    expect(page.url()).toContain('/gear')

    // Content should fit within mobile viewport
    const body = page.locator('body')
    const boundingBox = await body.boundingBox()
    expect(boundingBox?.width).toBeLessThanOrEqual(375)

    // Main content should still be visible
    const mainContent = page.locator('main, [role="main"]')
    await expect(mainContent).toBeVisible()
  })

  test('is responsive on desktop', async ({ page }) => {
    // Test desktop viewport  
    await page.setViewportSize({ width: 1920, height: 1080 })
    await page.reload()
    await page.waitForLoadState('domcontentloaded')

    // Should utilize wider desktop space
    const body = page.locator('body')
    const boundingBox = await body.boundingBox()
    expect(boundingBox?.width).toBeGreaterThan(768) // Should use desktop width

    // Main content should be visible and properly laid out
    const mainContent = page.locator('main, [role="main"]')
    await expect(mainContent).toBeVisible()
  })

  test('shows user is signed in', async ({ page }) => {
    // Look for sign out button or user avatar to confirm authentication
    const signOutButton = page.getByRole('button', { name: /sign out|logout/i })
    const userAvatar = page.locator('[data-testid="user-avatar"], .avatar')
    const userMenu = page.locator('[data-testid="user-menu"]')

    // At least one indicator of authenticated state should be present
    const authIndicators = [
      await signOutButton.count(),
      await userAvatar.count(),
      await userMenu.count()
    ]

    const hasAuthIndicator = authIndicators.some(count => count > 0)
    expect(hasAuthIndicator).toBe(true)
  })
})

