import { test, expect } from '@playwright/test'

// Gear form component tests - focused on form functionality
test.describe('Gear Form Component', () => {
  test.beforeEach(async ({ page }) => {
    // Skip if no Supabase credentials
    if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
      test.skip('Skipping gear form tests - no Supabase credentials available')
    }

    // Navigate to gear page where the form is used
    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')
    await page.waitForSelector('main, [role="main"]', { timeout: 10000 })

    // Ensure we're authenticated (not redirected to login)
    if (page.url().includes('/login')) {
      throw new Error('Authentication failed - redirected to login page')
    }
  })

  // Helper function to open the gear form
  async function openGearForm(page) {
    // Try different add button selectors in order of specificity
    const addButtonSelectors = [
      'button:has-text("Add Gear")',
      'button:has-text("Add")',
      '[data-testid="add-gear-button"]',
      '[data-testid="add-button"]',
      'button[class*="bg-primary"]', // Primary button styling
      'button[aria-label*="add" i]',
    ]

    let addButton = null
    for (const selector of addButtonSelectors) {
      const button = page.locator(selector)
      if (await button.count() === 1 && await button.isVisible()) {
        addButton = button
        break
      }
    }

    if (!addButton) {
      // Look for floating action button or icon-only buttons
      const iconButtons = page.locator('button').filter({ hasText: '' })
      for (let i = 0; i < await iconButtons.count(); i++) {
        const button = iconButtons.nth(i)
        if (await button.isVisible()) {
          // Check if it looks like an add button (circular, primary color, etc.)
          const classes = await button.getAttribute('class') || ''
          if (classes.includes('rounded-full') || classes.includes('bg-primary')) {
            addButton = button
            break
          }
        }
      }
    }

    if (!addButton) {
      test.skip('No add gear button found on page')
    }

    await addButton.click()
    await page.waitForTimeout(1000) // Give form time to appear

    // Try to find the form with different selectors
    const formSelectors = [
      '[data-testid="gear-form"]',
      'form:has([name="name"])',
      '[role="dialog"] form',
      '.modal form',
      'form',
    ]

    let form = null
    for (const selector of formSelectors) {
      const formElement = page.locator(selector)
      if (await formElement.count() > 0 && await formElement.isVisible()) {
        form = formElement.first()
        break
      }
    }

    if (!form) {
      test.skip('Gear form not found after clicking add button')
    }

    return form
  }

  test.describe('Form Opening and Basic Fields', () => {
    test('opens form when add button is clicked', async ({ page }) => {
      const form = await openGearForm(page)

      // Form should be visible
      await expect(form).toBeVisible()

      // Should have essential form fields
      const nameField = form.locator('input[name="name"], input[placeholder*="name" i], #name')
      const weightField = form.locator('input[name="weight"], input[placeholder*="weight" i], #weight')

      await expect(nameField.first()).toBeVisible()
      await expect(weightField.first()).toBeVisible()
    })

    test('shows required form fields', async ({ page }) => {
      const form = await openGearForm(page)

      // Test for presence of key fields with flexible selectors
      const fieldSelectors = [
        { name: 'Name', selectors: ['[name="name"]', '#name', 'input[placeholder*="name" i]'] },
        { name: 'Weight', selectors: ['[name="weight"]', '#weight', 'input[placeholder*="weight" i]'] },
        { name: 'Category', selectors: ['[name="category"]', '#category', 'select', '[role="button"]:has-text("Category")'] },
      ]

      for (const field of fieldSelectors) {
        let found = false
        for (const selector of field.selectors) {
          const element = form.locator(selector)
          if (await element.count() > 0 && await element.first().isVisible()) {
            found = true
            break
          }
        }
        expect(found, `${field.name} field should be present`).toBe(true)
      }
    })
  })

  test.describe('Form Validation', () => {
    test('validates required fields', async ({ page }) => {
      const form = await openGearForm(page)

      // Find submit button
      const submitButton = form.locator('button[type="submit"], button:has-text("Save"), button:has-text("Add")')

      if (await submitButton.count() === 0) {
        test.skip('Submit button not found')
      }

      // Try to submit empty form
      await submitButton.first().click()

      // Look for validation messages or focus on required fields
      const validationMessages = page.locator('[role="alert"], .error, .invalid, [data-testid*="error"]')
      const nameField = form.locator('[name="name"], #name, input[placeholder*="name" i]').first()

      // Either validation messages appear or name field gets focus
      const hasValidation = await validationMessages.count() > 0
      const nameIsFocused = await nameField.evaluate(el => document.activeElement === el)

      expect(hasValidation || nameIsFocused).toBe(true)
    })

    test('accepts valid form data', async ({ page }) => {
      const form = await openGearForm(page)

      // Fill in minimum required data
      const nameField = form.locator('[name="name"], #name, input[placeholder*="name" i]').first()
      const weightField = form.locator('[name="weight"], #weight, input[placeholder*="weight" i]').first()

      await nameField.fill('Test Gear Item')
      await weightField.fill('150')

      // Submit form
      const submitButton = form.locator('button[type="submit"], button:has-text("Save"), button:has-text("Add")')
      await submitButton.first().click()

      // Form should either close or show success state
      // We'll check that no error messages appear
      await page.waitForTimeout(2000)
      const errorMessages = page.locator('[role="alert"].error, .alert-destructive, [data-testid*="error"]')
      expect(await errorMessages.count()).toBe(0)
    })
  })

  test.describe('Responsive Behavior', () => {
    test('adapts to mobile viewport', async ({ page }) => {
      await page.setViewportSize({ width: 375, height: 667 })
      await page.reload()
      await page.waitForLoadState('domcontentloaded')

      const form = await openGearForm(page)

      // Form should still be usable on mobile
      await expect(form).toBeVisible()

      // Fields should be stacked vertically (not side by side)
      const nameField = form.locator('[name="name"], #name, input[placeholder*="name" i]').first()
      const weightField = form.locator('[name="weight"], #weight, input[placeholder*="weight" i]').first()

      const nameBox = await nameField.boundingBox()
      const weightBox = await weightField.boundingBox()

      if (nameBox && weightBox) {
        // On mobile, weight field should be below name field
        expect(weightBox.y).toBeGreaterThan(nameBox.y)
      }
    })

    test('utilizes desktop space', async ({ page }) => {
      await page.setViewportSize({ width: 1200, height: 800 })
      await page.reload()
      await page.waitForLoadState('domcontentloaded')

      const form = await openGearForm(page)

      // Form should be visible and well-laid-out
      await expect(form).toBeVisible()

      // Should have reasonable form width (not too narrow or too wide)
      const formBox = await form.boundingBox()
      if (formBox) {
        expect(formBox.width).toBeGreaterThan(300)
        expect(formBox.width).toBeLessThan(800)
      }
    })
  })
})

