// Helper functions
async function findAddButton(page) {
  const selectors = [
    'button:has-text("Add Gear")',
    'button:has-text("Add")', 
    '[data-testid="add-gear-button"]',
    'button[class*="bg-primary"]',
    'button[aria-label*="add" i]',
  ]

  for (const selector of selectors) {
    const button = page.locator(selector)
    if (await button.count() === 1 && await button.isVisible()) {
      return button
    }
  }

  // Fallback: look for floating action buttons
  const iconButtons = page.locator('button').filter({ hasText: '' })
  for (let i = 0; i < await iconButtons.count(); i++) {
    const button = iconButtons.nth(i)
    if (await button.isVisible()) {
      const classes = await button.getAttribute('class') || ''
      if (classes.includes('rounded-full') || classes.includes('bg-primary')) {
        return button
      }
    }
  }

  throw new Error('Add button not found')
}

async function findGearForm(page) {
  const selectors = [
    '[data-testid="gear-form"]',
    'form:has([name="name"])',
    '[role="dialog"] form',
    '.modal form',
    'form'
  ]

  for (const selector of selectors) {
    const form = page.locator(selector)
    if (await form.count() > 0 && await form.isVisible()) {
      return form.first()
    }
  }

  throw new Error('Gear form not found')
}

async function fillGearForm(form, data) {
  // Fill name
  if (data.name) {
    const nameField = form.locator('[name="name"], #name, input[placeholder*="name" i]').first()
    await nameField.fill(data.name)
  }

  // Fill weight
  if (data.weight) {
    const weightField = form.locator('[name="weight"], #weight, input[placeholder*="weight" i]').first()
    await weightField.fill(data.weight)
  }

  // Fill brand if present
  if (data.brand) {
    const brandField = form.locator('[name="brand"], #brand, input[placeholder*="brand" i]').first()
    if (await brandField.count() > 0) {
      await brandField.fill(data.brand)
    }
  }
}

