import { test, expect } from '@playwright/test'

// End-to-end user flows for gear management
test.describe('Gear Management Flows', () => {
  test.beforeEach(async ({ page }) => {
    // Skip if no Supabase credentials
    if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
      test.skip('Skipping gear management flow tests - no Supabase credentials available')
    }

    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')
    await page.waitForSelector('main, [role="main"]', { timeout: 10000 })

    // Ensure authentication worked
    if (page.url().includes('/login')) {
      throw new Error('Authentication failed - redirected to login page')
    }
  })

  test.describe('Add Gear Flow', () => {
    test('complete add gear workflow', async ({ page }) => {
      // 1. Open add gear form
      const addButton = await findAddButton(page)
      await addButton.click()

      // 2. Fill out gear form
      const form = await findGearForm(page)
      await fillGearForm(form, {
        name: 'Test Backpack',
        weight: '1200',
        brand: 'TestBrand',
        category: 'Pack'
      })

      // 3. Submit form
      const submitButton = form.locator('button[type="submit"], button:has-text("Save"), button:has-text("Add")')
      await submitButton.first().click()

      // 4. Verify gear was added (look for it in the list)
      await page.waitForTimeout(2000)
      const gearList = page.locator('text="Test Backpack"')
      await expect(gearList.first()).toBeVisible({ timeout: 5000 })
    })

    test('handles form errors gracefully', async ({ page }) => {
      const addButton = await findAddButton(page)
      await addButton.click()

      const form = await findGearForm(page)

      // Submit form with invalid data
      const weightField = form.locator('[name="weight"], #weight, input[placeholder*="weight" i]').first()
      await weightField.fill('-50') // Invalid negative weight

      const submitButton = form.locator('button[type="submit"], button:has-text("Save"), button:has-text("Add")')
      await submitButton.first().click()

      // Should show validation error
      const errorMessage = page.locator('[role="alert"], .error, .invalid, [data-testid*="error"]')
      await expect(errorMessage.first()).toBeVisible({ timeout: 3000 })
    })
  })

  test.describe('Navigation Flow', () => {
    test('user can navigate through app sections', async ({ page }) => {
      // Should be on gear page
      expect(page.url()).toContain('/gear')

      // Look for navigation elements
      const navElements = [
        page.getByRole('link', { name: /dashboard/i }),
        page.getByRole('link', { name: /lists/i }),
        page.getByRole('link', { name: /profile/i }),
        page.locator('nav a'),
      ]

      let foundNav = false
      for (const nav of navElements) {
        if (await nav.count() > 0 && await nav.first().isVisible()) {
          foundNav = true
          break
        }
      }

      // Should have some form of navigation available
      expect(foundNav).toBe(true)
    })

    test('maintains authentication across page navigation', async ({ page }) => {
      // Start on gear page (authenticated)
      expect(page.url()).toContain('/gear')

      // Try navigating to root/dashboard
      await page.goto('/dashboard')
      await page.waitForLoadState('domcontentloaded')

      // Should not be redirected to login
      await page.waitForTimeout(2000)
      expect(page.url()).not.toContain('/login')

      // Should show authenticated content
      const signOutButton = page.getByRole('button', { name: /sign out|logout/i })
      expect(await signOutButton.count()).toBeGreaterThan(0)
    })
  })

  test.describe('Search and Filter Flow', () => {
    test('user can search for gear items', async ({ page }) => {
      // Look for search functionality
      const searchBox = page.locator('input[placeholder*="search" i], input[type="search"]')

      if (await searchBox.count() === 0) {
        test.skip('Search functionality not found')
      }

      // Perform search
      await searchBox.first().fill('backpack')
      await page.waitForTimeout(1000)

      // Results should update (this is a basic test - results may be empty)
      // The important thing is that search doesn't crash the app
      const body = page.locator('body')
      await expect(body).toBeVisible()
    })

    test('user can filter by category', async ({ page }) => {
      // Look for category filter
      const categoryFilter = page.locator('button, select').filter({ hasText: /categor/i })

      if (await categoryFilter.count() === 0) {
        test.skip('Category filter not found')
      }

      // Try interacting with category filter
      await categoryFilter.first().click()
      await page.waitForTimeout(500)

      // Should show category options or dropdown
      const options = page.locator('[role="option"], option, [data-testid*="category"]')
      const hasOptions = await options.count() > 0

      // If no specific options found, at least the click shouldn't crash
      const body = page.locator('body')
      await expect(body).toBeVisible()
    })
  })
})

// Helper functions
async function findAddButton(page) {
  const selectors = [
    'button:has-text("Add Gear")',
    'button:has-text("Add")', 
    '[data-testid="add-gear-button"]',
    'button[class*="bg-primary"]',
    'button[aria-label*="add" i]',
  ]

  for (const selector of selectors) {
    const button = page.locator(selector)
    if (await button.count() === 1 && await button.isVisible()) {
      return button
    }
  }

  // Fallback: look for floating action buttons
  const iconButtons = page.locator('button').filter({ hasText: '' })
  for (let i = 0; i < await iconButtons.count(); i++) {
    const button = iconButtons.nth(i)
    if (await button.isVisible()) {
      const classes = await button.getAttribute('class') || ''
      if (classes.includes('rounded-full') || classes.includes('bg-primary')) {
        return button
      }
    }
  }

  throw new Error('Add button not found')
}

async function findGearForm(page) {
  const selectors = [
    '[data-testid="gear-form"]',
    'form:has([name="name"])',
    '[role="dialog"] form',
    '.modal form',
    'form'
  ]

  for (const selector of selectors) {
    const form = page.locator(selector)
    if (await form.count() > 0 && await form.isVisible()) {
      return form.first()
    }
  }

  throw new Error('Gear form not found')
}

async function fillGearForm(form, data) {
  // Fill name
  if (data.name) {
    const nameField = form.locator('[name="name"], #name, input[placeholder*="name" i]').first()
    await nameField.fill(data.name)
  }

  // Fill weight
  if (data.weight) {
    const weightField = form.locator('[name="weight"], #weight, input[placeholder*="weight" i]').first()
    await weightField.fill(data.weight)
  }

  // Fill brand if present
  if (data.brand) {
    const brandField = form.locator('[name="brand"], #brand, input[placeholder*="brand" i]').first()
    if (await brandField.count() > 0) {
      await brandField.fill(data.brand)
    }
  }
}

